from research_helpers import *
A=ev('https://www.sec.gov/Archives/edgar/data/1509190/000150919019000018/petx-20181231x10k.htm','Aratana2018 annual report: three marketed medicines, species-specific capromorelin formulation, licensed clinical candidates and terminated VetStem licence. Historical developer/licensee evidence, not current ownership inference.')
H=ev('https://www.sec.gov/Archives/edgar/data/1509190/000150919015000005/petx-20141231x10k.htm','Historical named AT006/007/008/009/010/011/012/015/016/017/018 programmes and species; does not establish current clinical activity.')
D=ev('https://www.sec.gov/Archives/edgar/data/1509190/000150919018000010/petx-20171231x10k.htm','BLONTRESS and TACTRESS discontinued November2017; AT007 development discontinued2016; rights to AT016 terminated effective midApril2018.')
F=ev('https://www.sec.gov/Archives/edgar/data/1509190/000150919015000047/petx-20151105ex991fff922.htm','AT011 canine parvovirus programme explicitly discontinued2015.')
E=ev('https://my.elanco.com/us/campaign/elura','Current successor marketed feline capromorelin oral solution20mg/mL, distinct from canine formulation.')
M=ev('https://my.elanco.com/us/resources','Current successor lists Galliprant and Nocita product resources; other Elanco medicines not automatically Aratana products.')
S=ev('https://investor.elanco.com/investor-resources/investor-faqs','Elanco confirms completed Aratana corporate acquisition July18 2019; subsidiary identity not all parent portfolio.')
ps=[p('GALLIPRANT','Grapiprant tablets for canine osteoarthritis pain and inflammation; historical Aratana developer/licensee.',A,'commercial',roles=['developer','licensee'],aliases=['AT-001'],typ='product',evidence=[A,M]),p('ENTYCE','Canine capromorelin oral formulation for appetite stimulation; historical marketed Aratana product.',A,'unknown',roles=['developer','licensee'],typ='product',attributes={'development_code':'AT-002; canine formulation','current_marketing_status_unverified':True}),p('NOCITA','Bupivacaine liposome injectable suspension for veterinary postoperative pain.',A,'commercial',roles=['developer','licensee'],aliases=['AT-003'],typ='product',evidence=[A,M]),p('ELURA','Feline capromorelin20mg/mL oral formulation for weight loss in cats with chronic kidney disease.',E,'commercial',roles=['developer','licensee'],typ='product',evidence=[A,E],attributes={'development_code':'AT-002; feline formulation','concentration_mg_per_ml':20,'species':'cat'}),p('BLONTRESS','Historical canine B-cell lymphoma monoclonal antibody; discontinued November2017.',D,'discontinued',aliases=['AT-004']),p('TACTRESS','Historical canine T-cell lymphoma monoclonal antibody; discontinued November2017.',D,'discontinued',aliases=['AT-005']),p('Aratana canine osteosarcoma live Listeria vaccine','Historical licensed HER2/neu-directed canine therapeutic vaccine; USDA conditional licence2017, current status unverified.',A,'unknown',roles=['developer','licensee'],aliases=['AT-014'],attributes={'historical_regulatory_status':'USDA conditional licence2017','original_licensor':'Advaxis'})]
for code,desc,life,src in [('AT-006','Eprociclovir licensed from Ajinomoto for feline herpesvirus ophthalmic disease.','unknown',A),('AT-007','Historical feline immunodeficiency virus programme; development discontinued2016.','discontinued',D),('AT-008','Rabacfosadine licensed outside North America for canine lymphoma; North American VetDC Tanovea rights not Aratana rights.','unknown',A),('AT-009','Historical canine mast-cell tumour lead-selection programme.','unknown',H),('AT-010','Historical canine atopic-dermatitis lead-selection programme.','unknown',H),('AT-011','Historical canine parvovirus programme; discontinued2015.','discontinued',F),('AT-012','Historical feline calicivirus programme.','unknown',H),('AT-015','Historical feline lymphoma proof-of-concept programme.','unknown',H),('AT-016','Historical VetStem allogeneic adipose stem-cell canine osteoarthritis programme; Aratana licence terminated midApril2018.','unknown',A),('AT-017','Historical canine lymphoma lead-selection programme.','unknown',H),('AT-018','Timapiprant CRTH2 antagonist licensed from Atopix for canine atopic dermatitis.','unknown',A),('AT-019','EP4 receptor antagonist licensed from AskAt in2018 for pain/inflammation.','unknown',A)]:
 ps.append(p('Aratana '+code,desc,src,life,attributes={'development_code':code,'historical_programme':True,'current_successor_activity':'unverified'}))
for x in ps:x.setdefault('attributes',{})['company_relationship_scope']='Aratana-developed/licensed product; acquired by Elanco2019, not all Elanco products';x['evidence'].append(S)
cs=[company('Aratana Therapeutics Inc',ps,[A,H,D,F,E,M,S],'Nineteen distinct veterinary identities reviewed; feline and canine capromorelin formulations separated without ambiguous shared AT002 alias. Discontinued lymphoma/antiviral products and ended VetStem licence recorded. Exact current legacy dispositions, drug strengths/territories and Elura historical code continuity to reconcile fully; no automatic ownership of North American VetDC Tanovea.')]
P=ev('https://www.sec.gov/Archives/edgar/data/882104/000088210421000035/pdli-20201231.htm','PDL2020 annual report: Noden sold September9 2020; Tekturna/Rasilez and HCT brand mappings, authorized generic launch March2019; royalty holdings distinct from direct medicines.')
np=[p('TEKTURNA','Aliskiren branded tablets historically commercialized through PDL subsidiary Noden; regional brand Rasilez.',P,roles=['commercial_partner'],aliases=['RASILEZ'],typ='product',valid_to='2020-09-09'),p('TEKTURNA HCT','Aliskiren/hydrochlorothiazide fixed-combination tablets historically commercialized through Noden.',P,roles=['commercial_partner'],aliases=['RASILEZ HCT'],typ='product',valid_to='2020-09-09'),p('Noden authorized generic aliskiren tablets','Authorized generic of Tekturna launched by Noden USA March2019; distinct branded-labelled commercial offering.',P,roles=['commercial_partner'],typ='product',valid_to='2020-09-09')]
for x in np:x['attributes']={'company_relationship_scope':'historical parent commercial partner; Noden business sold September9 2020','current_lifecycle_unverified':True}
cs.append(company('PDL BioPharma Inc',np,[P],'Historical Noden branded/authorized-generic identities reconciled; September2020 parent relationship end recorded. Legacy PDL antibody development, Queen humanization platform, LENSAR ownership/spinoff and precise present medicine availability remain to research; royalty receivables not treated as ownership of every underlying drug.'))
(out/'batch-0099.json').write_text(json.dumps({'companies':cs},indent=2));print(sum(len(c['products']) for c in cs))
